2dcf905f-53d2-446c-a550-2acd225ab744	1368e337-dd1d-4799-bbb3-8221a1b79bcc	identity	{"tone": "conversational, direct, anti-corporate", "email": "finetuning@contactforsales.com", "phone": "+44 (0) 7934 524 911", "tagline": "AI for the Rest of Us", "industry": "AI consulting / technology services", "multiple": "industry: AI consulting and technology services | target_audience: UK SMEs including managing directors, operations managers, and technical founders seeking practical AI implementation | tone: plain-speaking, anti-hype, practitioner-led — direct and honest without jargon or inflated claims | purpose: lead generation for custom AI projects, positioning FineTuning as the credible no-nonsense alternative to big consultancies for businesses that want results not presentations", "company_name": "FineTuning", "tone_of_voice": "Plain-spoken and direct. We write like experienced practitioners talking to a busy business owner, not like a tech vendor pitching to a CTO. No buzzwords, no hype, no jargon without explanation. Confident but not arrogant. We acknowledge AI limitations honestly. Short sentences preferred. Active voice. UK English spelling. Avoid: 'leverage', 'cutting-edge', 'transformative', 'unlock', 'harness', 'game-changing', 'AI-powered' as a standalone claim. When in doubt, ask: would a sceptical SME owner roll their eyes at this? If yes, rewrite it.", "target_audience": "UK SMEs looking for practical AI solutions", "content_strategy": "Target audience: UK SME owners and managers, typically 5–50 employees, non-technical but commercially minded. Tone: plain-spoken, pragmatic, reassuring — no jargon, no hype, honest about what AI can and cannot do. Purpose: lead generation via consultation bookings, supported by trust-building content. Industry: AI consulting and advisory services. All content should speak directly to time-poor business owners who are sceptical of tech vendors and want straight answers."}	content-gap-planner	content-gap-planner	\N	\N	f	2026-0