fd977481-6ad5-4278-92bd-d5f1b5d61bbc	2a8ebf9c-20a2-4c39-b191-840b012371da	identity	{"tone": "professional yet approachable", "email": "agents@contactforsales.com", "phone": "+44 (0) 7934 524 911", "tagline": "Agile AI Agents: Move Swiftly into Digital Transformation with Grace and Precision", "industry": "AI consulting / agent orchestration / technology services", "services": [{"name": "Automated Website Solutions", "description": "Get production-ready websites up and running in minutes with our AI-powered multi-agent systems. We handle secure, scalable hosting on Cloudflare, including automated builds, testing, and launches – removing the usual hurdles so you can focus on what matters."}, {"name": "Multi-Agent Systems", "description": "We design custom hierarchical agent setups to address your business challenges. Supporting a range of LLMs and models, these systems delegate tasks sensibly, collaborate in real time, and scale smoothly for effective automation."}, {"name": "Digital Transformation Strategy", "description": "Clear guidance to integrate AI and modern technology into your everyday operations. We work with you to build straightforward roadmaps for AI adoption, streamlining workflows, and staying agile in a fast-changing world."}, {"name": "Web Consultancy", "description": "Practical advice on modern web architectures, smart deployment, and useful AI integrations. We help your team build solid, forward-thinking web applications that focus on speed, security, and real innovation."}], "company_name": "AI Agent Orchestration", "about_summary": "AI Agent Orchestration builds production-grade multi-agent systems on proven infrastructure — Kubernetes, Kafka, and Postgres. We design hierarchical agent architectures that automate complex workflows, from automated website deployment to real-time agent collaboration. No demos. No slide decks. Working systems, deployed and running.", "leadership_team": [{"bio": "Peter is a technology strategist with strong enthusiasm for AI agent frameworks, modern web architecture, and automated systems. He leads our efforts in digital transformation, delivering agile innovation through effective multi-agent orchestration and quick deployments.", "name": "Peter Grenfell", "title": "Founder & Principal Consultant"}], "target_audience": "CTOs, engineering leads, and technology decision-makers at mid-to-large enterprises and scaling startups who are evaluating or actively deploying AI agent systems in production environments. Secondary audience includes startup founders and forward-thinking business leaders seeking practical AI-driven automation with measurable outcomes.", "key_differentiators": "Our agile approach to AI orchestration\\nFast deployments (minutes instead of weeks)\\nSolid enterprise-level security and reliability\\nProven stack with Kubernetes, Kafka, and Postgres\\nStrong expertise in hierarchical multi-agent systems\\nSpecial focus on web automation – with room to grow into other areas", "target_audience_tone_purpose": "Target Audience: CTOs, engineering leads, VP Engineering, and technically sophisticated startup founders evaluating production AI infrastructure. Secondary: forward-thinking business owners who understand technology investment. Tone: Direct, confident, and technically credible — written by builders for builders. No fluff, no vague consulting language. Purpose: Lead generation and consultation bookings for AI agent orchestration engagements, supported by demonstration of deep technical competence through case studies, tooling, and blog content.", "industry_audience_tone_purpose": "Industry: AI infrastructure and enterprise automation. Target Audience: CTOs, engineering leads, and operations directors at mid-market to enterprise companies, plus scaling startup founders evaluating production AI agent deployments. Tone: confident, direct, and technically credible — written by builders for builders, not by consultants for executives. Purpose: generate qualified inbound leads for custom multi-agent system design and production deployment engagements."}	content-gap-planner	content-gap-planner	\N	\N	f	2026-03-15 08:48:22.312535+00	2026-03-18 02:24:26.685773+00	content-gap-planner	f
3eb0dea2-4ba0-46a9-90be-2510e6e5963d	1368e337-dd1d-4799-bbb3-8221a1b79bcc	identity	{"tone": "conversational, direct, anti-corporate", "email": "finetuning@contactforsales.com", "phone": "+44 (0) 7934 524 911", "tagline": "AI for the Rest of Us", "industry": "AI consulting / technology services", "multiple": "industry: AI consulting and technology services | target_audience: UK SMEs including managing directors, operations managers, and technical founders seeking practical AI implementation | tone: plain-speaking, anti-hype, practitioner-led — direct and honest without jargon or inflated claims | purpose: lead generation for custom AI projects, positioning FineTuning as the credible no-nonsense alternative to big consultancies for businesses that want results not presentations", "company_name": "FineTuning", "content_brief": "Primary audience: UK SME owners and senior managers, typically 5–50 employees, non-technical, sceptical of AI hype, looking for honest and practical guidance on where AI can genuinely save time or money. Tone: plain-spoken, pragmatic, reassuring — the voice of an experienced practitioner who has no interest in overselling. No jargon, no buzzwords, no breathless enthusiasm. Site purpose: generate discovery call bookings by building trust with an audience that has been burned by vague AI promises before. Every page should either educate, reassure, or move the reader toward booking a call. Industry verticals: broad UK SME, with emphasis on professional services, retail, and light manufacturing where operational efficiency gains are most tangible.", "tone_of_voice": "Plain-spoken and direct. We write like experienced practitioners talking to a busy business owner, not like a tech vendor pitching to a CTO. No buzzwords, no hype, no jargon without explanation. Confident but not arrogant. We acknowledge AI limitations honestly. Short sentences preferred. Active voice. UK English spelling. Avoid: 'leverage', 'cutting-edge', 'transformative', 'unlock', 'harness', 'game-changing', 'AI-powered' as a standalone claim. When in doubt, ask: would a sceptical SME owner roll their eyes at this? If yes, rewrite it.", "target_audience": "UK SME owners and senior managers at businesses with 5–50 employees, typically in service-based industries. Non-technical decision-makers who are curious about AI but sceptical of vendor hype. They want honest, practical guidance on where AI can save them time or money — not a technology lecture. They respond to plain English, real numbers, and proof that something works before they commit.", "content_strategy": "Target audience: UK SME owners and managers, typically 5–50 employees, non-technical but commercially minded. Tone: plain-spoken, pragmatic, reassuring — no jargon, no hype, honest about what AI can and cannot do. Purpose: lead generation via consultation bookings, supported by trust-building content. Industry: AI consulting and advisory services. All content should speak directly to time-poor business owners who are sceptical of tech vendors and want straight answers.", "editorial_metadata": "target_audience: UK SME owners and senior managers (5–50 employees), non-technical, sceptical of hype, seeking practical AI guidance; tone: plain-speaking, pragmatic, no jargon, experienced-practitioner voice; purpose: lead generation via discovery call bookings; industry: AI consulting and technology services for UK SMEs, with emphasis on professional services, retail, and light manufacturing"}	content-gap-planner	content-gap-planner	\N	\N	f	2026-03-15 03:50:12.709407+00	2026-03-15 07:55:08.087565+00	content-gap-planner	f
1b8ca30e-e4ee-464e-ba9c-fc4e27b9df13	1368e337-dd1d-4799-bbb3-8221a1b79bcc	briefing	{"tagline": "From idea to AI system", "about_us": "  Finetune is a small technical company focused on practical AI deployment.  We build systems that combine automation, data pipelines, model training, and agent-based architectures.  Our aim is to make AI genuinely useful.   ## AI systems that actually do the work  Most companies experimenting with AI end up with prototypes, demos, or chatbots.  Very few end up with systems that **save time, automate work, or generate measurable value**.  Finetune helps organisations design and deploy practical AI systems — automation pipelines, specialised models, and intelligent agents that solve real operational problems.  Not AI theatre.  ---  Real systems.  # Rapid experimentation  AI technology is moving quickly.  The companies that benefit most are those that can **experiment cheaply and deploy quickly**.  We aim to make it easy to test ideas, build prototypes, and evolve them into real systems when they prove useful.   ---  # What we build  We work with companies to build AI infrastructure that fits into real workflows.  ### Automation systems  AI that screens requests, processes documents, extracts information, and routes work automatically.  ### Intelligent agent pipelines  Systems where multiple AI agents collaborate to solve problems, analyse information, or complete complex tasks.  ### Custom AI models  Fine-tuned models trained on domain-specific data using techniques such as LoRA and other efficient training methods.  ### RAG systems for company knowledge  AI that can search and reason over internal data such as documents, emails, financial information, and knowledge bases.  ### Private AI deployments  Secure systems where models can run locally or within controlled environments to protect sensitive data.  ### Data collection infrastructure  Large-scale web data pipelines capable of gathering structured information from thousands of sources.  ---  # Why most AI projects fail  Many AI initiatives stall for predictable reasons.  **They start with tools instead of problems.**  **They stay in prototype mode.**  **They rely on third-party systems that can’t integrate with existing workflows.**  **Or they assume a single AI model will magically solve everything.**  In practice, useful AI systems usually require:  * data pipelines * automation layers * model adaptation * monitoring and iteration  AI works best as **part of a system**, not as a standalone tool.  ---  # The Finetune approach  We focus on **practical deployment**.  That means starting with a real operational problem and designing a system around it.  A typical project might involve:  1. Collecting and structuring the relevant data 2. Building automation pipelines 3. Training or adapting models 4. Integrating the system into existing workflows 5. Iterating until the system reliably saves time or improves decisions  The goal is not simply to use AI.  The goal is to make something **genuinely useful**.  ---  # What we can help with  Examples of problems we help solve:  * Screening and routing incoming requests * Automating quoting or proposal workflows * Extracting structured information from documents * Building internal knowledge assistants * Collecting market or financial data at scale * Deploying private AI models for sensitive workflows * Setting up agent pipelines that can perform complex multi-step tasks  Some systems are simple and highly targeted.  Others involve networks of cooperating agents and large-scale data pipelines.  ---  # A note on scale  We are particularly interested in **agent systems and large-scale automation**.  This includes experimentation with environments where thousands of AI agents can communicate and collaborate to solve problems.  These systems are still emerging, but they point toward a future where much of the routine work inside organisations can be handled by coordinated software agents.  Our goal is to help companies begin exploring that future in a practical way.  ---    ---  # Who we work with  We tend to work best with organisations that:  * have complex workflows or data * are open to experimentation * want to build internal capability with AI rather than just outsource it  This includes startups, established companies, and technical teams exploring new ways to operate.  ---  # About Finetune  Finetune is a small technical company focused on practical AI deployment.  We build systems that combine automation, data pipelines, model training, and agent-based architectures.  Our focus is simple:  **make AI genuinely useful inside real organisations.**  ---  # Call to action  ## Curious what AI could automate in your business?  We’re always happy to have a technical conversation about possible approaches.  Contact us to discuss your workflows, data, or ideas.", "services": [{"name": "AI Automation Systems  ", "description": "Design and deployment of AI-driven automation pipelines that remove manual work from business processes. Examples include request screening, automated quoting, document analysis, and workflow orchestration."}, {"name": "Intelligent Agent Systems", "description": "Design and deployment of networks of AI agents capable of solving complex tasks collaboratively. These systems can analyse information, communicate with each other, and perform large-scale problem solving. Talk to us about systems capable of running tens of thousands of AI agents communicating with each other to solve complex tasks."}, {"name": "Custom AI Model Training", "description": "Training specialised models using techniques such as LoRA, DoRA, and other parameter-efficient methods to adapt modern AI models to your company's specific needs."}, {"name": "RAG Systems for Company Data", "description": "Deployment of Retrieval-Augmented Generation systems that allow AI to search and reason over your internal data including:  Emails  Documents  Financial records  Marketing material  Knowledge bases"}, {"name": "Bulk Data Collection", "description": "Large-scale web data extraction across thousands of websites, including structured business and financial data collection."}, {"name": "Financial and Company Data Pipelines", "description": "Automated systems for collecting and analysing financial data from public sources including company registries and regulatory filings."}, {"name": "Private AI Deployments", "description": "Secure deployment of AI systems that run privately — including models that can run locally or in-browser to protect company data and reduce usage costs."}, {"name": "Agent Pipeline Infrastructure", "description": "Installation and configuration of agent frameworks and orchestration systems so companies can run their own AI agents in production."}, {"name": "Rapid Website Generation", "description": "Creation of complex, high-quality static websites within minutes for:  company identity  marketing pages  landing pages  documentation  presentations"}, {"name": "AI Strategy & Implementation", "description": "Hands-on support helping companies move from curiosity about AI to systems that actually work inside their business."}, {"name": "High-Volume Data Acquisition", "description": "Design systems capable of collecting structured information from thousands of websites automatically."}], "company_name": "FineTuning"}	pageflow-builder	briefing-agent	\N	\N	f	2026-03-18 14:15:45.730262+00	2026-03-18 19:56:05.369657+00	briefing-agent	f
1c2de956-f9f4-49d9-a659-13c66b792b14	4851f6fc-71cf-4160-a270-e03d6d3e0732	voice	{"content_voice": "Content voice is anchored in the leopardess brand metaphor: precision, agility, speed, and stealth. These are not decorative — they map directly to engineering outcomes. Precision = deterministic agent behaviour, typed contracts, observable pipelines. Agility = iterative delivery cadence, composable architecture, fast feedback loops. Speed = time-to-production measured in days, not sprints. Stealth = low operational overhead, systems that run quietly without constant human intervention. Headlines and body copy should use this vocabulary to describe specific technical outcomes rather than generic transformation language. Banned phrases: 'digital transformation', 'production-ready' (unless followed by a specific stack qualifier), 'days not months' (unless paired with a concrete delivery example), 'AI-powered' (unqualified). Preferred framing: name the problem, name the system that solves it, name the outcome. Example rewrite — instead of 'production-ready AI systems delivered in days not months', prefer 'orchestrated agent pipelines on Kubernetes, scoped and deployed within a two-week engagement'. The primary audience evaluates vendors on specificity; vague benefit language signals low credibility to CTOs and engineering leads.", "tone_and_register": "All copy must maintain a single consistent register: technically precise, direct, and credible. Brand language ('Grace and Precision', 'Leopardess') is permitted as a framing device but must always resolve into a concrete technical or delivery claim within the same sentence or paragraph. Brand metaphors must never stand alone or substitute for specificity. The pattern is: brand framing → technical substance, not brand framing → benefit language. Example: 'Grace and Precision means your orchestration layer handles failover without manual intervention — not that we care deeply about your outcomes.' Aspirational or poetic phrasing that is not immediately grounded in a system behaviour, stack component, or delivery outcome should be removed or rewritten. This applies to all pages including index, about, and services."}	content-gap-planner	content-gap-planner	\N	\N	f	2026-03-15 02:09:21.699185+00	2026-03-15 08:36:57.003059+00	content-gap-planner	f
5f9de1c5-2dad-4b98-bac1-6df64852c9ff	e1e22a7d-0552-405a-85b3-1b1e51384df5	site_plan	{"pages": [{"name": "index", "title": "Spark | Where You Play", "sections": ["provocation-card", "lobby-grid", "brief-explanation", "gauntlet-cta"], "in_footer": true, "in_header": true, "nav_label": "Play", "nav_order": 1, "page_type": "index"}, {"name": "provocations", "title": "Today's Provocations | Spark", "sections": ["provocation-feed"], "in_footer": true, "in_header": true, "nav_label": "Provocations", "nav_order": 2, "page_type": "blog-index"}, {"name": "gauntlet", "title": "Daily Gauntlet | Spark", "sections": ["gauntlet-interface", "archetype-result-card"], "in_footer": true, "in_header": true, "nav_label": "Gauntlet", "nav_order": 3, "page_type": "tool"}, {"name": "about", "title": "What Is Spark | VONC", "sections": ["hero", "platform-comparison", "game-master-explanation", "gauntlet-cta"], "in_footer": true, "in_header": true, "nav_label": "About", "nav_order": 4, "page_type": "content"}, {"name": "archetypes", "title": "The 8 Archetypes | Spark", "sections": ["hero", "archetype-grid", "archetype-combinations"], "in_footer": true, "in_header": true, "nav_label": "Archetypes", "nav_order": 5, "page_type": "content"}, {"name": "contact", "title": "Contact", "sections": null, "in_footer": true, "in_header": true, "nav_label": "Contact", "nav_order": 6}], "site_type": "interactive-platform", "needs_logo": true, "needs_images": true, "design_intent": {"avoid": ["Corporate aesthetics", "Stock photography of any kind", "Light or white backgrounds", "Rounded friendly UI patterns", "Generic social media iconography", "Gradient backgrounds that feel like SaaS landing pages", "Testimonial carousels", "Generic feature grids with checkmark icons", "Any AI-generated faces or people", "Serif fonts", "Muted or pastel color palettes", "Traditional website hero sections with background images", "Any element that feels like scrolling a feed"], "colour_mood": "Deep charcoal and near-black base (#0a0a0f to #1a1a2e) with electric vibrant accents. Primary accent: vivid electric orange (#ff6b2b). Secondary accents: cyan (#00d4ff), magenta (#ff2d78), gold (#ffc107). Accents are used sparingly but with high contrast — they should pop like HUD elements in a dark interface. No pastels, no muted tones, no corporate blue. The palette should feel like neon signage in a dark room.", "style_direction": "Arena-dark-vibrant — darker and more energetic than standard professional-dark. This should feel like entering a competitive gaming lobby, not reading a corporate website. Every element should carry game energy.", "typography_mood": "Sharp, modern, slightly condensed headings that feel like game UI — think Inter Tight, Space Grotesk, or similar geometric sans-serifs with personality. Body text clean and highly readable against dark backgrounds. Monospace elements for timers, scores, and game mechanics. Type hierarchy is aggressive — headlines are large and punchy, body text is compact. No serif fonts, no handwritten fonts, no rounded friendly fonts.", "imagery_direction": "Abstract, geometric, atmospheric. No photographs of people. No stock imagery. No screenshots of interfaces. All imagery should feel like game environment art — dark spaces with vibrant accent lighting, geometric shapes suggesting cards and arenas, energy patterns and grid systems. Icons for archetypes should feel like character class symbols. Everything should reinforce the arena/lobby metaphor.", "layout_preference": "Card-based, grid-driven, mobile-first. The provocation card is the atomic unit — everything builds from card shapes. Generous dark space between elements. Content blocks feel like rooms or zones you enter, not sections you scroll past. Timer and score elements are first-class UI citizens. Interactive elements have visible state changes — hover states that feel like targeting, active states that feel like selection. No traditional website layouts — no hero-with-stock-photo, no three-column features grid with icons."}, "image_prompts": {"logo": "A bold, minimal logomark for 'Spark' — an abstract spark or ignition symbol that feels like a game icon, not a corporate logo. Sharp geometric edges with a sense of kinetic energy. Should work as a small favicon and a large brand mark. Electric yellow-orange on dark background. Think esports team logo meets minimalist tech brand. No gradients, no swooshes, no generic flame shapes.", "hero_home": "Abstract dark arena environment — imagine looking into a competitive gaming lobby from above. Dark charcoal and near-black background with electric accent lines in vivid orange, cyan, and magenta. Geometric card shapes floating in space suggesting provocation cards. Subtle grid pattern underneath. Timer elements and energy indicators as ambient visual elements. No people, no screens, no stock photo energy. Pure atmosphere — like the moment before a match starts.", "hero_about": "Split visual comparison — three zones representing Watch (passive, dim, grey-blue), Shout (chaotic, red, fragmented), and Play (vibrant, structured, electric). Abstract and geometric. The Play zone should dominate with sharp card shapes and arena energy. Dark background throughout. No literal social media logos or screenshots.", "archetype_judge": "Abstract geometric icon — balanced, authoritative, decisive. Deep crimson accent on dark background. Suggests scales, verdicts, final calls.", "archetype_maker": "Abstract geometric icon — constructive, layered, crafted. Warm copper accent on dark background. Suggests building, assembly, creation from raw materials.", "archetype_scout": "Abstract geometric icon — directional, searching, discovering. Bright cyan accent on dark background. Suggests radar, discovery, finding signal in noise.", "hero_archetypes": "Eight abstract geometric icons arranged in a constellation pattern on a dark background. Each icon has a distinct color from a vibrant palette — surgical steel blue, chaotic magenta, oracle gold, catalyst green, judge crimson, maker copper, scout cyan, mentor amber. Icons should feel like character class symbols from a game — sharp, distinctive, immediately recognizable at small sizes. Connected by faint energy lines suggesting relationships.", "archetype_mentor": "Abstract geometric icon — guiding, structured, supportive. Rich amber accent on dark background. Suggests pathways, elevation, teaching through experience.", "archetype_oracle": "Abstract geometric icon — all-seeing, layered, depth. Rich gold accent on dark background. Suggests foresight, pattern recognition, seeing what others miss.", "archetype_surgeon": "Abstract geometric icon — precise, angular, surgical. Steel blue accent on dark background. Suggests precision cutting, exact measurement, clinical accuracy. Sharp clean lines.", "archetype_catalyst": "Abstract geometric icon — explosive, radiating, transformative. Electric green accent on dark background. Suggests chain reactions, amplification, ignition.", "archetype_wildcard": "Abstract geometric icon — chaotic, asymmetric, unpredictable. Vivid magenta accent on dark background. Suggests disruption, surprise, energy that breaks patterns."}, "strategy_notes": "Following the roadmap strictly for v1_content_first phase. The roadmap specifies 5 pages with specific section_types that override the standard component list. I'm using the roadmap's section_types exactly as specified (provocation-card, lobby-grid, brief-explanation, gauntlet-cta, provocation-feed, gauntlet-interface, archetype-result-card, platform-comparison, game-master-explanation, archetype-grid, archetype-combinations). The hero section on about and archetypes pages maps to the standard hero component. No contact page is included per roadmap — this is a game platform, not a business site. Style collection is professional-dark as the closest match to the arena-dark-vibrant aesthetic specified, though the design_intent pushes it further into game territory with vibrant accent colors. The gauntlet page is typed as 'tool' and provocations as 'blog-index' per the domain strategy's page_type recommendations.", "style_collection": "professional-dark", "content_direction": {"voice": "Direct, confident, slightly competitive. Speaks like a game announcer who respects the players — not hype-man energy, but arena-host energy. Short declarative sentences. Present tense. Second person ('you'). Assumes the reader has opinions and is ready to use them. Never explains why having opinions is good — takes it as given. Slightly provocative without being edgy. The copy should make you want to play, not read more.", "emphasis": "The game mechanic is the message. Every piece of copy should either (1) get the visitor into a provocation, (2) get them into the Gauntlet, or (3) explain just enough to make them want to do one of those things. Emphasise: you play not post, AI is game master not performer, archetypes are earned not chosen, rooms not feeds, ephemeral challenges with permanent reputation. The Daily Gauntlet is the primary conversion action across every page.", "avoid_phrases": ["Join the conversation", "Share your voice", "Be part of the community", "Sign up today", "Don't miss out", "Revolutionary platform", "Cutting-edge AI", "Powered by artificial intelligence", "Social media reimagined", "The future of social", "Content creation", "Engage with content", "Your feed", "Algorithm", "Scroll", "Post", "Like and subscribe", "We believe that", "In today's world", "Leveraging", "Synergy", "Ecosystem", "Disruptive", "Game-changing", "Next-generation"], "blog_strategy": "Provocations ARE the blog strategy. Each daily provocation is an indexable, shareable content unit tied to real-world events. No traditional blog posts, no thought leadership, no 'how to use Spark' guides. The provocations feed builds topical SEO relevance over time by being genuinely tied to what is happening in the world. Each provocation URL is designed to be shared as a game invitation, not read as an article. Future content expansion comes from archetype analysis and arena recap content, not editorial.", "social_proof_style": "No testimonials in v1 — the platform has no users yet and fabricating social proof would undermine credibility. Instead, social proof comes from the game mechanics themselves: the provocation card IS the proof that the product works. Future social proof will come from shared archetype cards and Gauntlet completion stats displayed as live counters. When social proof is eventually added, it should be player stats and archetype distribution data, never quote-and-headshot testimonials."}}	build-site-planner	build-site-planner	\N	\N	t	2026-04-02 14:08:33.00762+00	\N	build-site-planner	f
5bc4069c-f292-4822-a40b-4b87248d3375	4851f6fc-71cf-4160-a270-e03d6d3e0732	voice	{"tone": "Authoritative-technical throughout. All copy — including CTAs, hero text, about page, and microcopy — should address senior engineering and technical leadership directly. Language should reflect production credibility and system depth. Avoid casual phrases ('Work Smarter, Not Harder'), motivational filler, or SMB-oriented softening language. CTAs should be action-specific and technically grounded (e.g. 'Review the Architecture', 'See How We Deploy', 'Start a Technical Conversation') rather than generic or inspirational. The voice is that of a senior engineer who also understands business outcomes — precise, confident, and free of consultant clichés.", "content_voice": "Content voice is anchored in the leopardess brand metaphor: precision, agility, speed, and stealth. These are not decorative — they map directly to engineering outcomes. Precision = deterministic agent behaviour, typed contracts, observable pipelines. Agility = iterative delivery cadence, composable architecture, fast feedback loops. Speed = time-to-production measured in days, not sprints. Stealth = low operational overhead, systems that run quietly without constant human intervention. Headlines and body copy should use this vocabulary to describe specific technical outcomes rather than generic transformation language. Banned phrases: 'digital transformation', 'production-ready' (unless followed by a specific stack qualifier), 'days not months' (unless paired with a concrete delivery example), 'AI-powered' (unqualified). Preferred framing: name the problem, name the system that solves it, name the outcome. Example rewrite — instead of 'production-ready AI systems delivered in days not months', prefer 'orchestrated agent pipelines on Kubernetes, scoped and deployed within a two-week engagement'. The primary audience evaluates vendors on specificity; vague benefit language signals low credibility to CTOs and engineering leads.", "tone_and_register": "All copy must maintain a single consistent register: technically precise, direct, and credible. Brand language ('Grace and Precision', 'Leopardess') is permitted as a framing device but must always resolve into a concrete technical or delivery claim within the same sentence or paragraph. Brand metaphors must never stand alone or substitute for specificity. The pattern is: brand framing → technical substance, not brand framing → benefit language. Example: 'Grace and Precision means your orchestration layer handles failover without manual intervention — not that we care deeply about your outcomes.' Aspirational or poetic phrasing that is not immediately grounded in a system behaviour, stack component, or delivery outcome should be removed or rewritten. This applies to all pages including index, about, and services."}	content-gap-planner	content-gap-planner	\N	\N	f	2026-03-15 08:36:57.015787+00	2026-03-15 08:37:49.87645+00	content-gap-planner	f
38c0e5a8-6037-487d-ab31-80ccdc768b33	4851f6fc-71cf-4160-a270-e03d6d3e0732	voice	{"tone": "Authoritative-technical throughout. All copy — including CTAs, hero text, about page, and microcopy — should address senior engineering and technical leadership directly. Language should reflect production credibility and system depth. Avoid casual phrases ('Work Smarter, Not Harder'), motivational filler, or SMB-oriented softening language. CTAs should be action-specific and technically grounded (e.g. 'Review the Architecture', 'See How We Deploy', 'Start a Technical Conversation') rather than generic or inspirational. The voice is that of a senior engineer who also understands business outcomes — precise, confident, and free of consultant clichés.", "content_voice": "Content voice is anchored in the leopardess brand metaphor: precision, agility, speed, and stealth. These are not decorative — they map directly to engineering outcomes. Precision = deterministic agent behaviour, typed contracts, observable pipelines. Agility = iterative delivery cadence, composable architecture, fast feedback loops. Speed = time-to-production measured in days, not sprints. Stealth = low operational overhead, systems that run quietly without constant human intervention. Headlines and body copy should use this vocabulary to describe specific technical outcomes rather than generic transformation language. Banned phrases: 'digital transformation', 'production-ready' (unless followed by a specific stack qualifier), 'days not months' (unless paired with a concrete delivery example), 'AI-powered' (unqualified). Preferred framing: name the problem, name the system that solves it, name the outcome. Example rewrite — instead of 'production-ready AI systems delivered in days not months', prefer 'orchestrated agent pipelines on Kubernetes, scoped and deployed within a two-week engagement'. The primary audience evaluates vendors on specificity; vague benefit language signals low credibility to CTOs and engineering leads.", "tone_and_register": "All copy must maintain a single consistent register: technically precise, direct, and credible. Brand language ('Grace and Precision', 'Leopardess') is permitted as a framing device but must always resolve into a concrete technical or delivery claim within the same sentence or paragraph. Brand metaphors must never stand alone or substitute for specificity. The pattern is: brand framing → technical substance, not brand framing → benefit language. Example: 'Grace and Precision means your orchestration layer handles failover without manual intervention — not that we care deeply about your outcomes.' Aspirational or poetic phrasing that is not immediately grounded in a system behaviour, stack component, or delivery outcome should be removed or rewritten. This applies to all pages including index, about, and services.", "tone_and_audience_targeting": "Primary audience is CTOs, engineering leads, and technical founders at UK scale-ups and B2B SaaS companies. All CTAs, hero copy, and section headlines must use technical-credibility language consistent with this audience. Phrases like 'Work Smarter, Not Harder', 'Get started in minutes', or other SMB-accessible idioms are out of scope and should be replaced with language that signals production depth, engineering rigour, and measurable outcomes (e.g. 'Deploy your first agent pipeline in a single sprint', 'Built on Kubernetes, Kafka, and Postgres — not wrappers'). Non-technical SMB buyers are explicitly out of scope and no page should contain copy that targets or accommodates them. Where a page currently mixes tones, the technical-enterprise register takes precedence and accessible language should be removed or rewritten."}	content-gap-planner	content-gap-planner	\N	\N	t	2026-03-15 08:37:49.881935+00	\N	content-gap-planner	f
8efe0378-0888-41cf-8112-5d252351e626	4851f6fc-71cf-4160-a270-e03d6d3e0732	identity	{"team": [{"bio": "Over 30 years of engineering experience. Built and operated worldsoccernews.com with sustained top search placement for competitive terms across a decade. Former senior engineer at Bumble. Strong financial systems background. Designed this multi-agent orchestration framework on Kubernetes and Kafka from first principles — workflow-driven state machines with Postgres persistence, coordinating 30+ specialised agent types across websites, data pipelines, news aggregation, and research systems. The architecture: each named agent here is itself an orchestrator managing teams of specialist agents, not a single prompt, and not just prompting.", "name": "Peter Grenfell", "photo": "", "title": "Principal Consultant"}, {"bio": "AI managing agent. Orchestrates a team of specialist research agents across multiple data acquisition strategies: deep web search with source attribution, structured extraction from industry registries, Companies House verification cascades with financial enrichment, news aggregation with credibility scoring, and competitive analysis. The research layer runs before any content generation or data publication — every output is sourced and verifiable. The same research infrastructure that grounds website content also powers standalone data collection pipelines.", "name": "Archivist", "photo": "", "title": "Head of Research"}, {"bio": "AI managing agent. Coordinates a team of specialist auditors across every deployed system — content quality, structural integrity, tool functionality, CSS consistency, data pipeline health, and deployment status. Each auditor runs independently with its own detection logic and severity classification. Findings route to specialist fix agents or escalate to human review based on confidence. Full audit trails with processing history on every finding, fix, and verification.", "name": "Sentinel", "photo": "", "title": "Head of Quality Assurance"}, {"bio": "AI managing agent. Runs continuous improvement cycles across all deployed infrastructure. Coordinates specialist agents for content freshness, tool health, navigation integrity, news feed reliability, data quality monitoring, and deployment verification. Each cycle is fully observable — work items track every finding through triage, fix, and verification. Human review gates configurable per workflow stage. The system improves autonomously between human review cycles.", "name": "Quartermaster", "photo": "", "title": "Head of Operations"}], "tone": "professional yet approachable", "email": "leopardess@contactforsales.com", "phone": "+44 (0) 7934 524 911", "tagline": "Agile AI Agents: Move Swiftly into Digital Transformation with Grace and Precision", "industry": "AI consulting / agent orchestration / technology services", "services": [{"name": "Automated Website Solutions", "description": ""}, {"name": "Multi-Agent Systems", "description": ""}, {"name": "Digital Transformation Strategy", "description": ""}, {"name": "Web Consultancy", "description": ""}], "site_brief": "Industry: AI consulting and agent orchestration (technology services). Primary audience: Three personas — (1) CTOs and engineering leads at UK scale-ups (50–500 employees) who need proof of production deployments and working code, not slide decks; (2) Founders of B2B SaaS or professional services firms who are technically literate, lack an internal AI/ML team, and need a delivery partner who can own end-to-end build; (3) Operations and transformation leads at mid-market UK businesses seeking practical automation of high-volume workflows without hiring a full data engineering team. All three personas are time-poor, results-driven, and respond to specificity, working demos, and clear ROI framing. Tone: Practical, direct, technically credible — the voice of engineers who build real systems, not consultants who produce reports. Conversion purpose: Generate qualified inbound leads and demo requests from UK businesses ready to commission AI agent or automation work, with a secondary goal of establishing technical authority through case studies, tools, and insights content.", "company_name": "Leopardess Consulting", "about_summary": "At Leopardess Consulting, we like building smart, hierarchical AI agent systems that help businesses adapt quickly and effectively. Using tools like Kubernetes for orchestration, Kafka for smooth messaging, and Postgres for reliable storage, we create solutions that automate complex workflows – think spinning up and launching full multipage websites on Cloudflare in no time. We're here to help you make the most of AI with practical, dependable approaches that suit your team.", "leadership_team": [{"bio": "Peter is a technology strategist with strong enthusiasm for AI agent frameworks, modern web architecture, and automated systems. He leads our efforts in digital transformation, delivering agile innovation through effective multi-agent orchestration and quick deployments.", "name": "Peter Grenfell", "title": "Founder & Principal Consultant"}], "target_audience": "Primary: CTOs, engineering leads, and technical founders at UK scale-ups and B2B SaaS companies who evaluate vendors on production credibility, stack depth, and delivery track record. Secondary: technically-literate business decision-makers capable of assessing system architecture and engineering quality. Non-technical SMB buyers are explicitly out of scope.", "key_differentiators": "Our agile approach to AI orchestration\\nFast deployments (minutes instead of weeks)\\nSolid enterprise-level security and reliability\\nProven stack with Kubernetes, Kafka, and Postgres\\nStrong expertise in hierarchical multi-agent systems\\nSpecial focus on web automation – with room to grow into other areas", "brand_voice_guidelines": "The Leopardess name is a live brand asset and should be referenced naturally at least once per page through metaphor rather than explicit explanation. The leopardess archetype carries: speed (fast delivery, rapid iteration, no slow consulting cycles), precision (targeted solutions, no wasted motion, surgical automation), adaptability (hunts in complex terrain, works across stacks and sectors), and instinct (pattern recognition, knowing where to move before the client does). Apply these qualities to describe how the team works, how systems are built, and how problems are approached. Examples: 'We move fast because we've already mapped the terrain', 'precision-built agents, not broad-brush automation', 'we don't advise from the sidelines — we hunt the problem alongside you'. Avoid forced or literal animal references. The metaphor should feel like a natural extension of the practical-expert voice, not a mascot gimmick.", "industry_audience_tone_purpose": "Industry: AI consulting and agent orchestration / technology services. Target Audience: CTOs and engineering leads at UK scale-ups (50–500 employees) who need proof of production deployments; founders of B2B SaaS or professional services companies evaluating build-vs-buy for agent orchestration; operations and transformation leads at mid-market UK businesses automating high-volume workflows. Tone: Direct, technically credible, evidence-led — the voice of practitioners who ship working systems, not consultants who produce decks. Purpose: Lead generation and service conversion, achieved by demonstrating technical depth, showing real production deployments, and giving time-poor technical buyers enough specificity to self-qualify and initiate contact.", "industry_target_audience_tone_purpose": "Industry: AI consulting and agent orchestration / technology services. Target Audience: Primary — CTOs, engineering leads, and technical founders at UK scale-ups and B2B SaaS companies who evaluate vendors on production credibility, stack depth, and delivery track record. Secondary — technically-literate business decision-makers capable of assessing system architecture and engineering quality. Non-technical SMB buyers are explicitly out of scope. Tone: Practical, direct, and technically specific. Written as engineers who build and ship production systems, not consultants who produce slide decks. Benefit-led or simplified language is only appropriate when used to frame a technical outcome, never as a substitute for technical specificity. Purpose: Establish Leopardess Consulting as a credible production-grade AI and agent orchestration partner for UK scale-ups — demonstrating stack depth (Kubernetes, Kafka, Postgres, LLM orchestration), delivery track record, and engineering rigour across all pages."}	content-gap-planner	content-gap-planner	\N	\N	t	2026-03-15 05:46:06.101873+00	\N	content-gap-planner	f
af9cc494-8c8b-42bc-ae0f-6bf74a397f7d	5fe15466-4e2e-4ff2-981e-98c1b7074002	identity	{"email": "gas@contactforsales.com", "phone": "+44 (0) 7934 524 911", "contact": {"email": null, "phone": null, "address": null, "location": null}, "tagline": null, "industry": "Energy & Fuel Distribution", "services": [{"name": "Wholesale Fuel Distribution", "description": "Bulk supply of gasoline and diesel to retailers and commercial clients"}, {"name": "Fleet Fuel Services", "description": "Fuel supply solutions for commercial fleet operations"}, {"name": "Natural Gas Distribution", "description": "Wholesale natural gas supply to industrial and commercial customers"}, {"name": "Rack Pricing Programs", "description": "Wholesale rack fuel pricing for resellers and distributors"}], "key_people": [], "company_name": "Gas Wholesalers", "sub_industry": "Wholesale Gas & Petroleum Products", "about_summary": "Gas Wholesalers appears to be a wholesale distribution company focused on gas and petroleum products. Based on the domain name and industry research, this likely involves the wholesale supply of gasoline, diesel, natural gas, or related energy products to retailers, fleet operators, or industrial clients. The company would operate in the B2B fuel distribution market.", "site_strategy": "Industry: Petroleum wholesale and fuel distribution. Target audience: Gas station owners, fuel retailers, commercial fleet operators, industrial facilities, convenience store chains, and businesses requiring bulk fuel purchases. Tone: Direct, professional, no-nonsense — written from the perspective of experienced industry insiders, not salespeople. Emphasis on reliability, pricing transparency, and straightforward service. Purpose: Generate qualified B2B leads from fuel buyers who need a dependable wholesale distribution partner.", "social_profiles": {}, "target_audience": "Gas station owners, fuel retailers, commercial fleet operators, industrial facilities, convenience store chains, and businesses requiring bulk fuel purchases", "competitors_found": ["econogas.ca", "igasusa.com"], "has_existing_site": false, "existing_site_quality": "none", "unique_selling_points": ["Wholesale pricing for bulk fuel purchases", "Direct terminal access and distribution networks", "B2B focused fuel supply solutions", "Competitive rack pricing programs"], "target_market_and_locale": "Confirm whether Gas Wholesalers operates in the UK, US, or another market. If UK-based: replace 'gasoline' with 'petrol' or 'fuel' throughout, use UK business conventions (VAT, pence per litre pricing references), and ensure phone numbers and address formats are UK-standard. If US-based: replace the +44 phone number with a US number and audit all contact details. Once confirmed, update the service-areas page to explicitly name the regions, counties, or states served so prospects can immediately determine if they are in the coverage zone.", "target_audience_and_purpose": "Primary industry vertical: wholesale fuel distribution. Target audience segments: (1) forecourt operators and gas station owners purchasing bulk fuel for resale, (2) commercial fleet managers seeking reliable fuel supply contracts and rack pricing, (3) industrial facilities and large commercial buyers requiring consistent volume delivery. Site purpose: lead generation — drive qualified inbound inquiries from buyers who need a dependable wholesale fuel partner. All content decisions should be evaluated against these guardrails: does it speak to one of these three segments, does it reinforce reliability and transparency, and does it move a prospect toward a contact or inquiry action.", "industry_audience_tone_purpose": "Industry: Wholesale Fuel Distribution (Energy & Fuel sector, B2B). Target Audience: Gas station owners, fuel retailers, commercial fleet operators, industrial facilities, convenience store chains, and bulk fuel buyers. Tone: Direct, no-nonsense, experienced industry insider — not promotional or salesy; communicates reliability and transparency. Purpose: Generate qualified B2B enquiries from businesses requiring wholesale fuel supply, rack pricing programs, fleet fuel services, or natural gas distribution.", "tagline_and_product_terminology": "Replace the current tagline 'Wholesale Gas Supply Solutions' with one that reflects the full product scope, such as 'Wholesale Fuel, Natural Gas & Specialty Gas Distribution' or 'Complete Wholesale Fuel & Gas Supply.' Define three canonical product categories for use across all pages: (1) Wholesale Fuel Distribution — gasoline, diesel, and refined petroleum products; (2) Natural Gas Distribution — commercial and industrial natural gas supply; (3) Specialty Gases — any non-commodity gas products referenced on the services page. Enforce this terminology framework site-wide so homepage subheadlines, service descriptions, page titles, and meta descriptions all use the same category names without variation.", "industry, target_audience, tone, purpose": "industry: 'wholesale fuel distribution'; target_audience: 'fuel retailers, fleet operators, commercial and industrial buyers'; tone: 'direct and professional'; purpose: 'generate qualified inbound leads for bulk fuel supply contracts'"}	content-gap-planner	content-gap-planner	\N	\N	f	2026-03-15 05:47:28.194091+00	2026-03-15 10:48:16.841198+00	content-gap-planner	f
65b5b235-ae0f-4c2a-8cc3-12cd01480da2	1368e337-dd1d-4799-bbb3-8221a1b79bcc	briefing	{"tagline": "From idea to AI system", "about_us": "  Finetune is a small technical company focused on practical AI deployment.  We build systems that combine automation, data pipelines, model training, and agent-based architectures.  Our aim is to make AI genuinely useful.   ## AI systems that actually do the work  Most companies experimenting with AI end up with prototypes, demos, or chatbots.  Very few end up with systems that **save time, automate work, or generate measurable value**.  Finetune helps organisations design and deploy practical AI systems — automation pipelines, specialised models, and intelligent agents that solve real operational problems.  Not AI theatre.  ---  Real systems.  # Rapid experimentation  AI technology is moving quickly.  The companies that benefit most are those that can **experiment cheaply and deploy quickly**.  We aim to make it easy to test ideas, build prototypes, and evolve them into real systems when they prove useful.   ---  # What we build  We work with companies to build AI infrastructure that fits into real workflows.  ### Automation systems  AI that screens requests, processes documents, extracts information, and routes work automatically.  ### Intelligent agent pipelines  Systems where multiple AI agents collaborate to solve problems, analyse information, or complete complex tasks.  ### Custom AI models  Fine-tuned models trained on domain-specific data using techniques such as LoRA and other efficient training methods.  ### RAG systems for company knowledge  AI that can search and reason over internal data such as documents, emails, financial information, and knowledge bases.  ### Private AI deployments  Secure systems where models can run locally or within controlled environments to protect sensitive data.  ### Data collection infrastructure  Large-scale web data pipelines capable of gathering structured information from thousands of sources.  ---  # Why most AI projects fail  Many AI initiatives stall for predictable reasons.  **They start with tools instead of problems.**  **They stay in prototype mode.**  **They rely on third-party systems that can’t integrate with existing workflows.**  **Or they assume a single AI model will magically solve everything.**  In practice, useful AI systems usually require:  * data pipelines * automation layers * model adaptation * monitoring and iteration  AI works best as **part of a system**, not as a standalone tool.  ---  # The Finetune approach  We focus on **practical deployment**.  That means starting with a real operational problem and designing a system around it.  A typical project might involve:  1. Collecting and structuring the relevant data 2. Building automation pipelines 3. Training or adapting models 4. Integrating the system into existing workflows 5. Iterating until the system reliably saves time or improves decisions  The goal is not simply to use AI.  The goal is to make something **genuinely useful**.  ---  # What we can help with  Examples of problems we help solve:  * Screening and routing incoming requests * Automating quoting or proposal workflows * Extracting structured information from documents * Building internal knowledge assistants * Collecting market or financial data at scale * Deploying private AI models for sensitive workflows * Setting up agent pipelines that can perform complex multi-step tasks  Some systems are simple and highly targeted.  Others involve networks of cooperating agents and large-scale data pipelines.  ---  # A note on scale  We are particularly interested in **agent systems and large-scale automation**.  This includes experimentation with environments where thousands of AI agents can communicate and collaborate to solve problems.  These systems are still emerging, but they point toward a future where much of the routine work inside organisations can be handled by coordinated software agents.  Our goal is to help companies begin exploring that future in a practical way.  ---    ---  # Who we work with  We tend to work best with organisations that:  * have complex workflows or data * are open to experimentation * want to build internal capability with AI rather than just outsource it  This includes startups, established companies, and technical teams exploring new ways to operate.  ---  # About Finetune  Finetune is a small technical company focused on practical AI deployment.  We build systems that combine automation, data pipelines, model training, and agent-based architectures.  Our focus is simple:  **make AI genuinely useful inside real organisations.**  ---  # Call to action  ## Curious what AI could automate in your business?  We’re always happy to have a technical conversation about possible approaches.  Contact us to discuss your workflows, data, or ideas.", "services": [{"name": "AI Automation Systems  ", "description": "Design and deployment of AI-driven automation pipelines that remove manual work from business processes. Examples include request screening, automated quoting, document analysis, and workflow orchestration."}, {"name": "Intelligent Agent Systems", "description": "Design and deployment of networks of AI agents capable of solving complex tasks collaboratively. These systems can analyse information, communicate with each other, and perform large-scale problem solving. Talk to us about systems capable of running tens of thousands of AI agents communicating with each other to solve complex tasks."}, {"name": "Custom AI Model Training", "description": "Training specialised models using techniques such as LoRA, DoRA, and other parameter-efficient methods to adapt modern AI models to your company's specific needs."}, {"name": "RAG Systems for Company Data", "description": "Deployment of Retrieval-Augmented Generation systems that allow AI to search and reason over your internal data including:  Emails  Documents  Financial records  Marketing material  Knowledge bases"}, {"name": "Bulk Data Collection", "description": "Large-scale web data extraction across thousands of websites, including structured business and financial data collection."}, {"name": "Financial and Company Data Pipelines", "description": "Automated systems for collecting and analysing financial data from public sources including company registries and regulatory filings."}, {"name": "Private AI Deployments", "description": "Secure deployment of AI systems that run privately — including models that can run locally or in-browser to protect company data and reduce usage costs."}, {"name": "Agent Pipeline Infrastructure", "description": "Installation and configuration of agent frameworks and orchestration systems so companies can run their own AI agents in production."}, {"name": "Rapid Website Generation", "description": "Creation of complex, high-quality static websites within minutes for:  company identity  marketing pages  landing pages  documentation  presentations"}, {"name": "AI Strategy & Implementation", "description": "Hands-on support helping companies move from curiosity about AI to systems that actually work inside their business."}, {"name": "High-Volume Data Acquisition", "description": "Design systems capable of collecting structured information from thousands of websites automatically."}], "company_name": "FineTuning"}	pageflow-builder	briefing-agent	\N	\N	f	2026-03-21 13:14:46.385511+00	2026-03-21 13:58:09.361046+00	briefing-agent	f
cb6bbefd-d45f-41a0-9012-9cc083293579	5fe15466-4e2e-4ff2-981e-98c1b7074002	identity	{"email": "gas@contactforsales.com", "phone": "+44 (0) 7934 524 911", "contact": {"email": null, "phone": null, "address": null, "location": null}, "tagline": null, "industry": "Energy & Fuel Distribution", "services": [{"name": "Wholesale Fuel Distribution", "description": "Bulk supply of gasoline and diesel to retailers and commercial clients"}, {"name": "Fleet Fuel Services", "description": "Fuel supply solutions for commercial fleet operations"}, {"name": "Natural Gas Distribution", "description": "Wholesale natural gas supply to industrial and commercial customers"}, {"name": "Rack Pricing Programs", "description": "Wholesale rack fuel pricing for resellers and distributors"}], "key_people": [], "company_name": "Gas Wholesalers", "sub_industry": "Wholesale Gas & Petroleum Products", "about_summary": "Gas Wholesalers appears to be a wholesale distribution company focused on gas and petroleum products. Based on the domain name and industry research, this likely involves the wholesale supply of gasoline, diesel, natural gas, or related energy products to retailers, fleet operators, or industrial clients. The company would operate in the B2B fuel distribution market.", "site_metadata": "Industry: Fuel Wholesale & Distribution. Target Audience: Gas station owners, fuel retailers, commercial fleet operators, industrial facilities, convenience store chains, and bulk fuel buyers. Tone: Direct, professional, and industry-knowledgeable — written as experienced insiders, not salespeople. Emphasise reliability, transparency, and no-nonsense service. Purpose: Generate wholesale fuel supply enquiries from qualified commercial and industrial buyers.", "site_strategy": "Industry: Petroleum wholesale and fuel distribution. Target audience: Gas station owners, fuel retailers, commercial fleet operators, industrial facilities, convenience store chains, and businesses requiring bulk fuel purchases. Tone: Direct, professional, no-nonsense — written from the perspective of experienced industry insiders, not salespeople. Emphasis on reliability, pricing transparency, and straightforward service. Purpose: Generate qualified B2B leads from fuel buyers who need a dependable wholesale distribution partner.", "social_profiles": {}, "target_audience": "Gas station owners, fuel retailers, commercial fleet operators, industrial facilities, convenience store chains, and businesses requiring bulk fuel purchases", "competitors_found": ["econogas.ca", "igasusa.com"], "has_existing_site": false, "existing_site_quality": "none", "unique_selling_points": ["Wholesale pricing for bulk fuel purchases", "Direct terminal access and distribution networks", "B2B focused fuel supply solutions", "Competitive rack pricing programs"], "target_market_and_locale": "Confirm whether Gas Wholesalers operates in the UK, US, or another market. If UK-based: replace 'gasoline' with 'petrol' or 'fuel' throughout, use UK business conventions (VAT, pence per litre pricing references), and ensure phone numbers and address formats are UK-standard. If US-based: replace the +44 phone number with a US number and audit all contact details. Once confirmed, update the service-areas page to explicitly name the regions, counties, or states served so prospects can immediately determine if they are in the coverage zone.", "target_audience_and_purpose": "Primary industry vertical: wholesale fuel distribution. Target audience segments: (1) forecourt operators and gas station owners purchasing bulk fuel for resale, (2) commercial fleet managers seeking reliable fuel supply contracts and rack pricing, (3) industrial facilities and large commercial buyers requiring consistent volume delivery. Site purpose: lead generation — drive qualified inbound inquiries from buyers who need a dependable wholesale fuel partner. All content decisions should be evaluated against these guardrails: does it speak to one of these three segments, does it reinforce reliability and transparency, and does it move a prospect toward a contact or inquiry action.", "industry_audience_tone_purpose": "Industry: Wholesale Fuel Distribution (Energy & Fuel sector, B2B). Target Audience: Gas station owners, fuel retailers, commercial fleet operators, industrial facilities, convenience store chains, and bulk fuel buyers. Tone: Direct, no-nonsense, experienced industry insider — not promotional or salesy; communicates reliability and transparency. Purpose: Generate qualified B2B enquiries from businesses requiring wholesale fuel supply, rack pricing programs, fleet fuel services, or natural gas distribution.", "tagline_and_product_terminology": "Replace the current tagline 'Wholesale Gas Supply Solutions' with one that reflects the full product scope, such as 'Wholesale Fuel, Natural Gas & Specialty Gas Distribution' or 'Complete Wholesale Fuel & Gas Supply.' Define three canonical product categories for use across all pages: (1) Wholesale Fuel Distribution — gasoline, diesel, and refined petroleum products; (2) Natural Gas Distribution — commercial and industrial natural gas supply; (3) Specialty Gases — any non-commodity gas products referenced on the services page. Enforce this terminology framework site-wide so homepage subheadlines, service descriptions, page titles, and meta descriptions all use the same category names without variation.", "industry, target_audience, tone, purpose": "industry: 'wholesale fuel distribution'; target_audience: 'fuel retailers, fleet operators, commercial and industrial buyers'; tone: 'direct and professional'; purpose: 'generate qualified inbound leads for bulk fuel supply contracts'"}	content-gap-planner	content-gap-planner	\N	\N	f	2026-03-15 10:48:16.854955+00	2026-03-15 10:49:21.184171+00	content-gap-planner	f
7133c647-cdcd-4b8c-9ad6-f8ae321e5adc	1368e337-dd1d-4799-bbb3-8221a1b79bcc	identity	{"tone": "conversational, direct, anti-corporate", "email": "finetuning@contactforsales.com", "phone": "+44 (0) 7934 524 911", "tagline": "AI for the Rest of Us", "industry": "AI consulting / technology services", "multiple": "industry: AI consulting and technology services | target_audience: UK SMEs including managing directors, operations managers, and technical founders seeking practical AI implementation | tone: plain-speaking, anti-hype, practitioner-led — direct and honest without jargon or inflated claims | purpose: lead generation for custom AI projects, positioning FineTuning as the credible no-nonsense alternative to big consultancies for businesses that want results not presentations", "company_name": "FineTuning", "content_brief": "Primary audience: UK SME owners and senior managers, typically 5–50 employees, non-technical, sceptical of AI hype, looking for honest and practical guidance on where AI can genuinely save time or money. Tone: plain-spoken, pragmatic, reassuring — the voice of an experienced practitioner who has no interest in overselling. No jargon, no buzzwords, no breathless enthusiasm. Site purpose: generate discovery call bookings by building trust with an audience that has been burned by vague AI promises before. Every page should either educate, reassure, or move the reader toward booking a call. Industry verticals: broad UK SME, with emphasis on professional services, retail, and light manufacturing where operational efficiency gains are most tangible.", "site_metadata": "ICP: UK SME owners and senior managers, 5–50 employees, service-based industries, non-technical, time-poor, sceptical of vendor hype. Tone: plain-spoken, direct, no-nonsense, practitioner credibility — no buzzwords, no jargon, real numbers where possible. Primary conversion goal: book a free consultation or initial call via the contact page. Secondary goal: build trust through honest, practical content so visitors self-qualify before reaching out.", "tone_of_voice": "Plain-spoken and direct. We write like experienced practitioners talking to a busy business owner, not like a tech vendor pitching to a CTO. No buzzwords, no hype, no jargon without explanation. Confident but not arrogant. We acknowledge AI limitations honestly. Short sentences preferred. Active voice. UK English spelling. Avoid: 'leverage', 'cutting-edge', 'transformative', 'unlock', 'harness', 'game-changing', 'AI-powered' as a standalone claim. When in doubt, ask: would a sceptical SME owner roll their eyes at this? If yes, rewrite it.", "target_audience": "UK SME owners and senior managers at businesses with 5–50 employees, typically in service-based industries. Non-technical decision-makers who are curious about AI but sceptical of vendor hype. They want honest, practical guidance on where AI can save them time or money — not a technology lecture. They respond to plain English, real numbers, and proof that something works before they commit.", "content_strategy": "Target audience: UK SME owners and managers, typically 5–50 employees, non-technical but commercially minded. Tone: plain-spoken, pragmatic, reassuring — no jargon, no hype, honest about what AI can and cannot do. Purpose: lead generation via consultation bookings, supported by trust-building content. Industry: AI consulting and advisory services. All content should speak directly to time-poor business owners who are sceptical of tech vendors and want straight answers.", "editorial_metadata": "target_audience: UK SME owners and senior managers (5–50 employees), non-technical, sceptical of hype, seeking practical AI guidance; tone: plain-speaking, pragmatic, no jargon, experienced-practitioner voice; purpose: lead generation via discovery call bookings; industry: AI consulting and technology services for UK SMEs, with emphasis on professional services, retail, and light manufacturing"}	content-gap-planner	content-gap-pla