5b8ecd3e-4052-4734-8b3b-8514f1cfed04	5fe15466-4e2e-4ff2-981e-98c1b7074002	tools	{"reasoning": "Gas Wholesalers serves B2B procurement managers, fleet operators, and fuel retailers who make volume purchasing decisions based on price, cost efficiency, and logistics. The most valuable tools would help these visitors estimate fuel costs, understand pricing structures, and calculate savings — directly supporting the sales conversation. Custom calculators around fuel volume, cost per litre/gallon, fleet consumption, and delivery cost estimation would be genuinely useful. None of the library tools are relevant to fuel distribution; they are all finance/property or creative tools.", "suggestions": [{"name": "Fuel Cost Estimator", "function": "tool-fuel-cost-estimator", "priority": 1, "complexity": "simple", "description": "Allows fleet managers and fuel buyers to input estimated monthly or annual fuel volume (litres/gallons), select fuel type (diesel, unleaded, natural gas), and receive an estimated wholesale cost range versus typical retail cost — illustrating potential savings from switching to wholesale supply. Directly supports lead generation on the fleet and wholesale pages.", "target_page": "fleet-fuel-services", "library_source": null, "tool_component_id": null}, {"name": "Bulk Fuel Delivery Calculator", "function": "tool-bulk-fuel-delivery-calculator", "priority": 2, "complexity": "simple", "description": "Helps gas station owners and commercial buyers calculate the cost of a bulk fuel order by entering volume (litres), current rack price, and delivery distance or zone. Outputs estimated total landed cost and cost per litre. Reinforces the rack pricing and wholesale distribution pages with a tangible, numbers-driven engagement tool.", "target_page": "rack-pricing-programs", "library_source": null, "tool_component_id": null}, {"name": "Fleet Fuel Consumption Analyser", "function": "tool-fleet-fuel-consumption-analyser", "priority": 3, "complexity": "simple", "description": "Lets fleet managers input number of vehicles, average daily mileage, and vehicle MPG/fuel efficiency to calculate estimated monthly fuel consumption in litres and projected annual fuel spend at current retail vs wholesale rates. Helps prospects self-qualify and understand the financial case for switching to a wholesale supplier.", "target_page": "fleet-fuel-services", "library_source": null, "tool_component_id": null}, {"name": "Unit Converter (Fuel Measurements)", "function": "tool-fuel-unit-converter", "priority": 4, "complexity": "simple", "description": "Converts between common fuel measurement units: litres, gallons (UK/US), barrels, therms, kWh, and MJ. Useful for procurement managers dealing with cross-border pricing, natural gas contracts, or switching between measurement standards. Practical utility tool that builds trust and repeat visits.", "target_page": "how-pricing-works", "library_source": null, "tool_component_id": null}], "rejected_tools": [{"reason": "Designed for marketing/conversion rate optimisation teams. Irrelevant to fuel procurement decision-makers.", "function": "tool-ab-test-calculator"}, {"reason": "AI image prompt builder — completely unrelated to fuel distribution or B2B energy procurement.", "function": "tool-prompt-architect"}, {"reason": "Star rating analysis tool for ecommerce/review contexts. No relevance to wholesale fuel supply.", "function": "tool-bayesian-ranking"}, {"reason": "Property finance tool. Not relevant to fuel buyers or fleet operators.", "function": "tool-bridging-loan-calculator"}, {"reason": "Buy-to-let property investment calculator. No relevance to this industry.", "function": "tool-btl-investor"}, {"reason": "Property equity finance tool. Not applicable to fuel wholesale customers.", "function": "tool-equity-release"}, {"reason": "Image editing tool. No practical use for B2B fuel procurement visitors.", "function": "tool-bg-remover"}, {"reason": "Consumer entertainment tool. Inappropriate for a professional B2B energy supplier.", "function": "tool-meme-generator"}, {"reason": "UK residential mortgage tool. Completely unrelated to fuel distribution.", "function": "tool-mortgage-affordability"}, {"reason": "Mortgage finance tool. No relevance to wholesale fuel buyers.", "function": "tool-mortgage-overpayment"}, {"reason": "Mortgage amortisation tool. Not relevant to this audience.", "function": "tool-mortgage-repayment"}, {"reason": "Cybersecurity/developer tool. Not relevant to fuel procurement professionals.", "function": "tool-password-entropy"}, {"reason": "Web design utility. Not useful for the site's visitor base of fleet managers and fuel buyers.", "function": "tool-favicon-generator"}, {"reason": "UK property tax calculator. No relevance to gas and petroleum wholesale distribution.", "function": "tool-stamp-duty-calculator"}]}	tool-suggester	tool-suggester	\N	LLM tool evaluation — reasoning, recommendations, and rejections	f	2026-04-02 10:27:22.105702+00	2026-04-02 10:33:07.382136+00	tool-suggester	f
