0e2ee5b3-44cc-4ad4-9312-408a4c9d7aa3	5fe15466-4e2e-4ff2-981e-98c1b7074002	tools	{"reasoning": "Gas Wholesalers serves B2B fuel procurement decision-makers — fleet managers, gas station owners, procurement directors — who need to quickly evaluate costs, savings, and logistics. The Fuel Cost Estimator is already deployed, which covers the core 'how much could I save?' question. Beyond that, genuinely useful tools would help visitors calculate delivery frequency, compare fuel pricing scenarios, or estimate carbon/emissions for compliance purposes. Most library tools are finance or marketing-focused and have no relevance here. A small number of custom tools could add real value for this specific audience.", "suggestions": [{"name": "Fuel Delivery Frequency Calculator", "function": "tool-delivery-frequency-calculator", "priority": 1, "complexity": "simple", "description": "Helps fleet managers and fuel retailers calculate optimal tank refill intervals based on tank capacity, daily consumption rate, and desired safety buffer. Outputs recommended delivery frequency and flags risk of runout. Directly useful for operations planning and supports conversations about supply scheduling.", "target_page": "fleet-fuel-services", "library_source": null, "tool_component_id": null}, {"name": "Rack vs Retail Price Comparison Tool", "function": "tool-rack-vs-retail-comparison", "priority": 2, "complexity": "simple", "description": "Allows resellers and independent retailers to input current retail pump price and local rack price to visualise margin spread, blended margin per gallon, and monthly margin at a given volume. Directly supports the rack-pricing-programs page and helps prospects self-qualify the value of switching.", "target_page": "rack-pricing-programs", "library_source": null, "tool_component_id": null}, {"name": "Fleet Fuel Budget Planner", "function": "tool-fleet-fuel-budget-planner", "priority": 3, "complexity": "simple", "description": "Lets fleet managers input vehicle 