7e5627ba-a15a-497d-a5ce-6c34f9621f6c	5fe15466-4e2e-4ff2-981e-98c1b7074002	tools	{"reasoning": "Gas Wholesalers serves B2B fuel procurement decision-makers — fleet managers, gas station owners, procurement directors — who need to make financial and operational calculations around fuel purchasing. Two tools are already deployed (Fuel Cost Estimator, Gas Unit Converter). The remaining high-value gaps are: a fuel tax/excise duty reference tool, a bulk delivery cost estimator, a fleet fuel consumption tracker, and a break-even volume calculator for switching to wholesale supply. These map directly to the questions a procurement manager or fleet operator would ask before committing to a wholesale supplier relationship. Mortgage, property, AI, and gaming tools are entirely irrelevant to this audience.", "suggestions": [{"name": "Wholesale Break-Even Volume Calculator", "function": "tool-breakeven-volume-calculator", "priority": 1, "complexity": "simple", "description": "Helps prospects calculate the minimum monthly fuel volume needed to justify switching to a wholesale supply contract. Inputs: current retail price per gallon, estimated wholesale rack price, fixed monthly contract or delivery fee, and current monthly spend. Output: break-even volume in gallons/litres and a clear yes/no on whether their current usage qualifies. Directly answers the pre-sales question that stalls most prospects before they contact a supplier.", "target_page": "how-pricing-works", "related_pages": ["rack-pricing-programs", "wholesale-fuel-distribution", "why-gas-wholesalers"], "library_source": null, "tool_component_id": null}, {"name": "Fleet Fuel Consumption & Budget Estimator", "function": "tool-fleet-fuel-budget-estimator", "priority": 2, "complexity": "simple", "description": "Fleet managers input number of vehicles, average miles per week per vehicle, average MPG (or litres/100km), and a fuel price per gallon to get a monthly and annual fuel budget projection. Includes a side-by-side comparison at retail vs. wholesale price to show potential savings at scale. Highly practical for fleet operators doing annual budget planning — a core audience segment.", "target_page": "fleet-fuel-services", "related_pages": ["fleet-fuel-services", "fuel-supply-by-industry", "tool-fuel-cost-estimator"], "library_source": null, "tool_component_id": null}, {"name": "Diesel vs. Natural Gas Cost Comparison Tool", "function": "tool-diesel-vs-natural-gas-comparison", "priority": 3, "complexity": "moderate", "description": "Allows industrial or commercial buyers to compare the per-unit energy cost of diesel versus natural gas for heating or process applications. Inputs: current diesel consumption (gallons/month), current diesel price, estimated natural gas equivalent (therms or MMBtu), and natural gas rate. Outputs: monthly cost comparison, annual cost difference, and approximate payback period if switching. Supports the natural gas distribution service line and addresses a real procurement decision.", "target_page": "natural-gas-distribution", "related_pages": ["natural-gas-distribution", "fuel-supply-by-industry", "how-pricing-works"], "library_source": null, "tool_component_id": null}, {"name": "Fuel Storage Tank Size Calculator", "function": "tool-fuel-tank-size-calculator", "priority": 4, "complexity": "simple", "description": "Helps buyers determine the optimal bulk storage tank capacity based on their consumption rate and desired resupply frequency. Inputs: daily fuel consumption in gallons, preferred days of supply buffer, and delivery lead time. Outputs: recommended minimum tank size, suggested reorder point, and estimated delivery frequency. Useful for gas station owners and industrial buyers evaluating whether bulk delivery is operationally feasible for their site.", "target_page": "wholesale-fuel-distribution", "related_pages": ["wholesale-fuel-distribution", "fleet-fuel-services", "faq"], "library_source": null, "tool_component_id": null}], "rejected_tools": [{