59cfbf42-01c6-410f-a39a-e1eba065486f	5fe15466-4e2e-4ff2-981e-98c1b7074002	tools	{"reasoning": "Gas Wholesalers serves B2B fuel procurement decision-makers — fleet managers, gas station owners, procurement directors — who think in numbers: cost per gallon, delivery volumes, budget forecasts, and fuel consumption. The two tools already deployed (Fuel Cost Estimator and Gas Unit Converter) cover the core savings and unit conversion use cases well. Remaining gaps are around fuel budget planning, carbon/emissions reporting (increasingly relevant for fleet operators), and diesel vs. alternative fuel comparisons. Library tools are almost entirely irrelevant (mortgage, gaming, AI, image tools). Two custom tools could genuinely serve this audience's day-to-day operational questions.", "suggestions": [{"name": "Fleet Fuel Budget Calculator", "function": "tool-fleet-fuel-budget", "priority": 1, "complexity": "simple", "description": "Allows fleet managers to input number of vehicles, average miles driven per month, average MPG, and current fuel price to calculate projected monthly and annual fuel spend. Optionally compares retail vs. wholesale pricing to show potential budget savings. Directly useful for procurement planning and internal budget justification conversations — a natural complement to the existing Fuel Cost Estimator which focuses on per-gallon savings rather than whole-fleet budgeting.", "target_page": "fleet-fuel-services", "related_pages": ["fleet-fuel-services", "how-pricing-works", "rack-pricing-programs"], "library_source": null, "tool_component_id": null}, {"name": "Fuel Tax & Excise Duty Estimator", "function": "tool-fuel-tax-estimator", "priority": 2, "complexity": "moderate", "description": "Helps fuel resellers and station operators estimate the federal and state excise tax component within their fuel purchase cost based on volume and fuel type (gasoline vs. diesel). Inputs: volume in gallons, state selection, fuel type. Output: estimated tax liability per load, effective cost per gallon after tax, and tax as a percentage of total cost. Useful for margin planning and understanding the true landed cost of wholesale fuel — a genuine daily-use calculation for rack pricing customers.", "target_page": "rack-pricing-programs", "related_pages": ["rack-pricing-programs", "how-pricing-works", "wholesale-fuel-distribution"], "library_source": null, "tool_component_id": null}], "rejected_tools": [{"reason": "Conversion rate testing is irrelevant to fuel procurement professionals visiting a wholesale supplier site.", "function": "tool-ab-test-calculator"}, {"reason": "AI automation ROI is not relevant to the fuel distribution buying decision.", "function": "tool-ai-agent-roi-estimator"}, {"reason": "Gas station owners and fleet managers are not here to evaluate AI adoption readiness.", "function": "tool-ai-readiness-quiz"}, {"reason": "Mortgage products have no connection to wholesale fuel distribution.", "function": "tool-mortgage-affordability"}, {"reason": "Irrelevant to this industry and audience.", "function": "tool-mortgage-repayment"}, {"reason": "Irrelevant to this industry and audience.", "function": "tool-mortgage-overpayment"}, {"reason": "UK property tax tool with no relevance to US fuel wholesale operations.", "function": "tool-stamp-duty-calculator"}, {"reason": "Property finance tool, not relevant to fuel procurement.", "function": "tool-bridging-loan-calculator"}, {"reason": "Buy-to-let investment tool with no connection to fuel distribution.", "function": "tool-btl-investor"}, {"reason": "Property equity tool, entirely off-domain.", "function": "tool-equity-release"}, {"reason": "Image editing tool with no relevance to B2B fuel buyers.", "function": "tool-bg-remover"}, {"reason": "Inappropriate for a professional B2B wholesale fuel supplier.", "function": "tool-meme-generator"}, {"reason": "Web design utility with no relevance to fuel procurement.", "function": "tool-favicon-generator"}, {"reason": "AI image prompt builder with no connection to fuel distribution.", "function": "tool-prompt-architect"}, {"reason": "Statistical ranking tool suited to review-heavy platforms, not B2B fuel supply.", "function": "tool-bayesian-ranking"}, {"reason": "Gaming-focused tool, entirely irrelevant.", "function": "tool-loot-probability-calculator"}, {"reason": "Gaming/entertainment archetype quiz with no relevance to fuel wholesale.", "function": "tool-archetype-taster-quiz"}, {"reason": "Gaming tool, not applicable to this industry.", "function": "tool-archetype-clash-calculator"}, {"reason": "Robotics engineering tool with no connection to fuel distribution.", "function": "tool-gripper-payload-calculator"}, {"reason": "Software architecture tool aimed at engineering teams, not fuel procurement managers.", "function": "tool-agent-complexity-estimator"}]}	tool-suggester	tool-suggester	\N	LLM tool evaluation — reasoning, recommendations, and rejections	t	2026-04-06 19:18:14.434481+00	\N	tool-suggester	f
31b74006-8e6e-468e-981c-e38f2895fadc	e1e22a7d-0552-405a-85b3-1b1e51384df5	identity	{"contact": {"email": null, "phone": null, "address": null, "location": null}, "tagline": "TikTok is where you watch. Twitter is where you shout. Spark is where you play.", "industry": "Digital Entertainment & Social Technology", "services": [{"name": "Daily Gauntlet", "description": "A 5-provocation, 5-minute daily quiz that surfaces your player archetype through your opinions and takes"}, {"name": "Arena Mode", "description": "Competitive take-submission rooms where users go head-to-head on provocations with scoring and outcomes"}, {"name": "Stage Mode", "description": "Creative showcase space for skill-based content with built-in audience and niche discovery"}, {"name": "Provocation Feed", "description": "Daily AI-framed provocations tied to current events, each with a shareable URL and SEO value"}, {"name": "Archetype System", "description": "Behaviour-emergent identity profiles earned through engagement, not self-reported — your reputation builds from how you play"}], "key_people": [], "company_name": "Spark", "sub_industry": "AI-Driven Competitive Opinion Gaming Platform", "about_summary": "Spark is an AI-powered social platform that turns real-world events and trending topics into daily competitive games. Instead of posting or scrolling, users engage by submitting takes on provocations, competing in timed arenas, and earning archetypes based on how they actually play. The AI acts as game master — framing, scoring, and curating — while humans provide all the wit, heat, and creativity.", "site_metadata": "tagline: 'Your opinion. Ranked in real time.' | industry: Social debate and opinion gaming | target_audience: Intellectually competitive, culturally engaged adults aged 18-35 who have strong takes and want to test them publicly against real opposition — includes creators who want skill recognition and curators who shape taste without producing content | purpose: User acquisition and sign-up, with the Daily Gauntlet as the primary conversion action | tone: Direct, confident, slightly competitive — arena-host not hype-man. Short declarative sentences. Present tense. Second person. Assumes the reader already has opinions and is ready to use them. Never explains why opinions matter. Slightly provocative without being edgy. Copy should make you want to play, not read more.", "social_profiles": {}, "target_audience": "Opinionated, culturally engaged people aged 18-35 who have strong takes on current events but find existing platforms either too passive (TikTok/Instagram) or too chaotic (Twitter/X). Includes creators wanting skill showcase with built-in audience, and curators and tastemakers who discover rather than produce.", "competitors_found": ["twitter.com", "tiktok.com", "reddit.com", "kahoot.com", "nytimes.com/games"], "has_existing_site": false, "existing_site_quality": "none", "unique_selling_points": ["You play, not post — opinion-first entry removes the blank-page barrier", "AI is the game master, never the performer — all wit and heat comes from humans", "Ephemeral challenges build permanent reputation — disposable content, lasting identity", "Archetypes emerge from behaviour, not self-reporting — your profile is earned", "Rooms not feeds — enter a space with energy, don't scroll a stream", "Dual modes: Arena for competitive takes, Stage for creative showcase"]}	content-gap-planner	content-gap-planner	\N	\N	t	2026-04-06 20:20:18.369281+00	\N	content-gap-planner	f
