828723c2-8527-46ec-81c3-7f0443bb87b3	00ff3af5-dad8-4770-9f70-3edc267a3c92	tools	{"reasoning": "Robot-hands.com serves industrial automation engineers and robotics integrators who need to make technical and commercial decisions about end-effectors. Useful tools would help them compare gripper specifications, estimate ROI on automation investments, or match grippers to payload/reach requirements. None of the library tools are relevant to industrial robotics — they are all finance, mortgage, marketing, or creative tools. Custom tools around payload capacity, gripper selection, or automation ROI would genuinely serve this audience.", "suggestions": [{"name": "Gripper Payload & Safety Factor Calculator", "function": "tool-gripper-payload-calculator", "priority": 1, "complexity": "simple", "description": "Calculates the required gripper force given part weight, acceleration, orientation (horizontal/vertical/inverted), and a configurable safety factor. Outputs minimum holding force required and recommends whether a given gripper spec is sufficient. Engineers use this constantly when specifying end-effectors for a new application.", "target_page": "product-detail", "library_source": null, "tool_component_id": null}, {"name": "Robot Automation ROI Estimator", "function": "tool-automation-roi-estimator", "priority": 2, "complexity": "simple", "description": "Estimates payback period and 3-year ROI for a robotic automation project. Inputs: number of shifts, operator hourly cost, cycle time improvement, system cost, and maintenance estimate. Outputs annual savings, payback period in months, and cumulative ROI chart. Helps engineers build a business case for purchasing decisions.", "target_page": "index", "library_source": null, "tool_component_id": null}, {"name": "End-Effector Compatibility Checker", "function": "tool-end-effector-compatibility", "priority": 3, "complexity": "simple", "description": "A guided selection tool where users input robot brand/model, payload class, f